for key, words in translations.items():
    p = work / f'translations/ro/full/chunks/{key}.json'
    data = json.loads(p.read_text())
    assert len(data['segments']) == len(words), (key,len(data['segments']),len(words))
    for segment, translation in zip(data['segments'],words):
        segment['translation'] = translation
    p.write_text(json.dumps(data,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
    print(key,len(words))
